import os
import ast
import json
import re
import onnxruntime
from collections.abc import Mapping, Sequence
from .motor_limits import resolve_motor_velocity_limits

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(
    r"^[+-]?(?:(?:\d+\.\d*)|(?:\.\d+)|(?:\d+))(?:[eE][+-]?\d+)?$"
)


def _parse_metadata_string(value: str):
    """Parse one ONNX metadata string into the most likely Python value.

    ONNX custom metadata values are always strings, but different exporters have
    historically used different conventions:
      - canonical JSON: ``false``, ``0.02``, ``[1,2]``, ``{"x":1}``
      - Python repr/literals: ``False``, ``None``, ``{'x': 1}``
      - plain display strings: ``darkwing2_bdx``

    This parser accepts the first two forms and leaves plain strings alone.
    """

    text = value.strip()
    if text == "":
        return value

    # Preferred path for new exports.
    try:
        return json.loads(text)
    except (TypeError, json.JSONDecodeError):
        pass

    lower = text.lower()
    if lower == "true":
        return True
    if lower == "false":
        return False
    if lower in ("none", "null"):
        return None

    # Tolerate older Python repr metadata, including True/False/None and
    # single-quoted dict/list strings.
    try:
        parsed = ast.literal_eval(text)
    except (ValueError, SyntaxError):
        parsed = None
    else:
        if isinstance(parsed, (Mapping, Sequence, str, int, float, bool, type(None))) and not isinstance(parsed, (bytes, bytearray)):
            return parsed

    # Last scalar fallback for strings such as +1, -2, 3.5, 1e-3.
    if _INT_RE.match(text):
        try:
            return int(text)
        except ValueError:
            pass
    if _FLOAT_RE.match(text):
        try:
            return float(text)
        except ValueError:
            pass

    return value


def _coerce_metadata_value(value):
    if isinstance(value, str):
        parsed = _parse_metadata_string(value)
        # Recurse because JSON/Python-literal strings can decode to nested
        # containers that themselves contain stringified primitives.
        if parsed is value:
            return value
        return _coerce_metadata_value(parsed)
    if isinstance(value, Mapping):
        return {str(k): _coerce_metadata_value(v) for k, v in value.items()}
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return [_coerce_metadata_value(v) for v in value]
    return value


def load_meta_data(raw: Mapping) -> dict:
    """Recursively parse ONNX custom metadata into Python values.

    This accepts both new canonical-JSON MJLab exports and older metadata where
    booleans/lists/dicts were stored using Python string representations.
    """

    return {str(k): _coerce_metadata_value(v) for k, v in raw.items()}


def _as_mapping(value, *, name: str) -> dict:
    value = _coerce_metadata_value(value)
    if not isinstance(value, Mapping):
        raise TypeError(f"Expected metadata {name!r} to be a mapping, got {type(value).__name__}: {value!r}")
    return dict(value)


def _as_list(value, *, name: str) -> list:
    value = _coerce_metadata_value(value)
    if isinstance(value, str) or not isinstance(value, Sequence):
        raise TypeError(f"Expected metadata {name!r} to be a list, got {type(value).__name__}: {value!r}")
    return list(value)


def _as_float(value, *, name: str, default=None) -> float:
    if value is None:
        if default is not None:
            return float(default)
        raise TypeError(f"Expected metadata {name!r} to be a float, got None")
    value = _coerce_metadata_value(value)
    try:
        return float(value)
    except (TypeError, ValueError) as exc:
        raise TypeError(f"Expected metadata {name!r} to be a float, got {value!r}") from exc


def _as_int(value, *, name: str, default=None) -> int:
    if value is None:
        if default is not None:
            return int(default)
        raise TypeError(f"Expected metadata {name!r} to be an int, got None")
    value = _coerce_metadata_value(value)
    try:
        return int(value)
    except (TypeError, ValueError) as exc:
        raise TypeError(f"Expected metadata {name!r} to be an int, got {value!r}") from exc


def _as_bool(value, *, name: str, default=False) -> bool:
    if value is None:
        return bool(default)
    value = _coerce_metadata_value(value)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        text = value.strip().lower()
        if text in ("true", "1", "yes", "y", "on"):
            return True
        if text in ("false", "0", "no", "n", "off", "none", "null", ""):
            return False
    raise TypeError(f"Expected metadata {name!r} to be a bool, got {value!r}")


def _as_float_list(value, *, name: str, expected_len=None) -> list[float]:
    values = _as_list(value, name=name)
    if expected_len is not None and len(values) != int(expected_len):
        raise ValueError(f"Expected metadata {name!r} length {expected_len}, got {len(values)}")
    return [_as_float(v, name=f"{name}[{i}]") for i, v in enumerate(values)]

def print_meta(d: Mapping, indent: int = 0, verbose: bool = False):
    all_keys = list(d.keys())
    # split into visible vs hidden
    visible_keys = [k for k in all_keys if not k.startswith('.')]
    hidden_keys  = [k for k in all_keys if k.startswith('.')] if verbose else []

    # decide print order: visible, then (if verbose) hidden
    key_groups = [visible_keys]
    if verbose:
        key_groups.append(hidden_keys)

    if not any(key_groups):
        return

    # compute padding across all keys we will print
    printed_keys = visible_keys + hidden_keys
    key_width = max(len(k) for k in printed_keys)

    def fmt(k): return f"{k}:".ljust(key_width + 1)

    # process each group in order
    for keys in key_groups:
        if not keys:
            continue

        # classify keys in this group
        simple_keys = []
        list_keys   = []
        dict_keys   = []
        for k in keys:
            v = d[k]
            if isinstance(v, Mapping):
                dict_keys.append(k)
            elif isinstance(v, Sequence) and not isinstance(v, str):
                list_keys.append(k)
            else:
                simple_keys.append(k)

        simple_keys.sort()
        list_keys.sort()
        dict_keys.sort()

        for k in simple_keys:
            v = _coerce_metadata_value(d[k])
            print("  " * indent + fmt(k), v)

        for k in list_keys:
            v = d[k]
            print("  " * indent + fmt(k))
            for item in v:
                if isinstance(item, Mapping):
                    print_meta(item, indent + 1, verbose)
                else:
                    print("  " * (indent + 1) + f"- {item}")

        for k in dict_keys:
            print("  " * indent + fmt(k))
            print_meta(d[k], indent + 1, verbose)

class OnnxInfer:
    def __init__(self, onnx_model_path, verbose=False, input_name="obs", awd=False):
        self.onnx_model_path = onnx_model_path
        self.ort_session = onnxruntime.InferenceSession(
            self.onnx_model_path, providers=["CPUExecutionProvider"]
        )
        self.meta = self.ort_session.get_modelmeta()
        meta_data = self.meta.custom_metadata_map
        self.input_name = input_name
        self.awd = awd

        # ONNX interface introspection.  MJLab/RSL-RL recurrent policies may
        # export as obs+h_in(+c_in) -> actions+h_out(+c_out); older Playground
        # policies are plain obs -> actions.  Keep this generic so both work.
        self._ort_inputs = list(self.ort_session.get_inputs())
        self._ort_outputs = list(self.ort_session.get_outputs())
        self._input_names = [x.name for x in self._ort_inputs]
        self._output_names = [x.name for x in self._ort_outputs]
        extra_inputs = [name for name in self._input_names if name != self.input_name]
        if extra_inputs:
            raise RuntimeError(
                "ONNX policy has unsupported non-observation inputs "
                f"{extra_inputs}. Export a stateless actor with a single "
                f"{self.input_name!r} input."
            )
        self._trace_count = 0
        self._trace_limit = int(os.environ.get("PLAYGROUND_ONNX_TRACE_STEPS", "20"))
        self._trace_dir = os.environ.get("PLAYGROUND_ONNX_TRACE_DIR")
        if os.environ.get("PLAYGROUND_ONNX_TRACE") and not self._trace_dir:
            self._trace_dir = "playground_onnx_trace"
        if self._trace_dir:
            os.makedirs(self._trace_dir, exist_ok=True)
        if os.environ.get("PLAYGROUND_ONNX_PRINT_SIGNATURE", "1") not in ("0", "false", "False"):
            self._print_onnx_signature()

        meta = {
            "Model":         os.path.basename(onnx_model_path),
            "Producer name": self.meta.producer_name,
            "Domain":        self.meta.domain,
            "Description":   self.meta.description,
            "Graph name":    self.meta.graph_name,
        }
        meta.update(meta_data)
        info = load_meta_data(meta)
        if not meta_data:
            return
        self.info = info

        self.joints = [str(x) for x in _as_list(info['.Joints'], name='.Joints')]
        self.action_offset = _as_float_list(info['.ActionOffset'], name='.ActionOffset', expected_len=len(self.joints))
        self.action_history_mode = info.get('.ActionHistoryMode', 'deep')
        self.initial_action_pose = _as_float_list(
            info.get('.InitialActionPose', self.action_offset),
            name='.InitialActionPose',
            expected_len=len(self.joints),
        )
        self.commands = info.get('.Commands')
        self.contacts = _as_bool(info.get('.Contacts', False), name='.Contacts', default=False)
        self.quat = _as_bool(info.get('.Quat', False), name='.Quat', default=False)
        self.projected = _as_bool(info.get('.Projected', False), name='.Projected', default=False)
        if not self.projected:
            self.projected = _as_bool(info.get('.Gravity', False), name='.Gravity', default=False)
        self.observation_layout = _coerce_metadata_value(
            info.get('ObservationLayout', info.get('.ObservationLayout'))
        )
        self.privileged_observation_layout = _coerce_metadata_value(
            info.get('PrivilegedObservationLayout', info.get('.PrivilegedObservationLayout'))
        )

        if self.commands == None:
            # Fallback on hardcoded
            self.commands = [
                "lin_vel_x",       # 0
                "lin_vel_y",       # 1
                "ang_vel_yaw",     # 2
                "height",          # 3
                "neck_pitch",      # 4
                "head_pitch",      # 5
                "head_yaw",        # 6
                "head_roll",       # 7
                "trunk_pitch_cmd", # 8
                "trunk_yaw_cmd",   # 9
                "trunk_roll_cmd",  # 10
            ]
        self.commands = [str(x) for x in _as_list(self.commands, name='.Commands')]
        self.command_size = len(self.commands)
        self.command_index = {name: i for i, name in enumerate(self.commands)}

        config = _as_mapping(info['.Config'], name='.Config')
        self.config = config
        self.KD = info['.KD']
        self.KP = info['.KP']
        self.sim_dt = _as_float(config.get('sim_dt'), name='.Config.sim_dt')
        self.ctrl_dt = _as_float(config.get('ctrl_dt'), name='.Config.ctrl_dt')
        self.action_scale = _as_float(config.get('action_scale'), name='.Config.action_scale')
        self.dof_vel_scale = _as_float(config.get('dof_vel_scale'), name='.Config.dof_vel_scale')
        self.max_motor_velocity = _as_float(config.get('max_motor_velocity', 21.0), name='.Config.max_motor_velocity')
        metadata_limits = info.get('.MotorVelocityLimits')
        if (
            isinstance(metadata_limits, Sequence)
            and not isinstance(metadata_limits, str)
            and len(metadata_limits) == len(self.joints)
        ):
            self.motor_velocity_limits = _as_float_list(
                metadata_limits,
                name='.MotorVelocityLimits',
                expected_len=len(self.joints),
            )
        else:
            self.motor_velocity_limits = resolve_motor_velocity_limits(config, self.joints)
        self.COMMANDS_RANGE_X = _as_float_list(config.get('lin_vel_x'), name='.Config.lin_vel_x', expected_len=2)
        self.COMMANDS_RANGE_Y = _as_float_list(config.get('lin_vel_y'), name='.Config.lin_vel_y', expected_len=2)
        self.COMMANDS_RANGE_THETA = _as_float_list(config.get('ang_vel_yaw'), name='.Config.ang_vel_yaw', expected_len=2)
        push_config = _as_mapping(config.get('push_config', {}), name='.Config.push_config')
        self.noise_config = _as_mapping(config.get('noise_config', {}), name='.Config.noise_config')
        self.walk_in_place_enable = _as_float(config.get('walk_in_place_prob', 0.0), name='.Config.walk_in_place_prob') != 0.0
        self.push_enable = _as_bool(push_config.get('enable', False), name='.Config.push_config.enable', default=False)
        self.push_mag_min, self.push_mag_max = _as_float_list(
            push_config.get('magnitude_range', [0.0, 0.0]),
            name='.Config.push_config.magnitude_range',
            expected_len=2,
        )
        self.push_int_min, self.push_int_max = _as_float_list(
            push_config.get('interval_range', [0.0, 0.0]),
            name='.Config.push_config.interval_range',
            expected_len=2,
        )
        raw = info.get('.nb_steps_in_period', info.get('nb_steps_in_period'))
        if raw is None:
            raise ValueError("Expected '.nb_steps_in_period' in ONNX metadata")
        self.nb_steps_in_period = _as_int(raw, name='.nb_steps_in_period')

        print_meta(info, 0, verbose)

    def has(self, cmd: str) -> bool:
        return cmd in self.command_index

    def index(self, cmd: str) -> int:
        return self.command_index.get(cmd)


    def _print_onnx_signature(self):
        def desc(x):
            return f"{x.name}: shape={getattr(x, 'shape', None)} type={getattr(x, 'type', None)}"

        print("ONNX inputs:")
        for x in self._ort_inputs:
            print("  " + desc(x))
        print("ONNX outputs:")
        for x in self._ort_outputs:
            print("  " + desc(x))

    def _feed_obs_array(self, inputs):
        import numpy as np

        arr = np.asarray(inputs, dtype=np.float32)
        if self.awd and arr.ndim == 1:
            arr = arr.reshape(1, -1)
        return arr.astype(np.float32, copy=False)

    def _trace_inference(self, obs, outputs, action):
        if not self._trace_dir or self._trace_count >= self._trace_limit:
            return
        import json
        import numpy as np
        from pathlib import Path

        idx = self._trace_count
        out_dir = Path(self._trace_dir)
        out_dir.mkdir(parents=True, exist_ok=True)
        np.savez(
            out_dir / f"onnx_infer_{idx:06d}.npz",
            obs=np.asarray(obs, dtype=np.float32),
            action=np.asarray(action, dtype=np.float32),
            **{f"output_{i}_{name}": np.asarray(v) for i, (name, v) in enumerate(zip(self._output_names, outputs))},
        )
        rec = {
            "i": idx,
            "model": os.path.basename(self.onnx_model_path),
            "inputs": self._input_names,
            "outputs": self._output_names,
            "obs_shape": list(np.asarray(obs).shape),
            "action_shape": list(np.asarray(action).shape),
            "action_min": float(np.min(action)),
            "action_max": float(np.max(action)),
            "action_norm": float(np.linalg.norm(action)),
        }
        with (out_dir / "summary.jsonl").open("a") as f:
            f.write(json.dumps(rec, sort_keys=True) + "\n")
        self._trace_count += 1

    def get_providers(self):
        return self.ort_session.get_providers()

    def infer(self, inputs):
        obs = self._feed_obs_array(inputs)
        outputs = self.ort_session.run(None, {self.input_name: obs})

        action = outputs[0]
        if self.awd and getattr(action, "ndim", 0) >= 2 and action.shape[0] == 1:
            action = action[0]
        self._trace_inference(obs, outputs, action)
        return action

if __name__ == "__main__":
    import argparse
    import numpy as np
    import time

    parser = argparse.ArgumentParser()
    parser.add_argument("-o", "--onnx_model_path", type=str, required=True)
    args = parser.parse_args()

    obs_size = 46

    oi = OnnxInfer(args.onnx_model_path, awd=True)
    times = []
    for i in range(1000):
        inputs = np.random.uniform(size=obs_size).astype(np.float32)
        # inputs = np.arange(obs_size).astype(np.float32)
        # print(inputs)
        start = time.time()
        print(oi.infer(inputs))
        times.append(time.time() - start)

    print("Average time: ", sum(times) / len(times))
    print("Average fps: ", 1 / (sum(times) / len(times)))
